161:                 }
162:                 CreateHero(heroData[i], startGrid, team, netIndex);
163:                 ++netIndex;
164:             }
165:         }
166:         else if (mapType == MapType.SuperHero)
167:         {
168:             int teamPlayerCount = heroLength / 3;
169:             PrepareTeamSpawnGrids(ref team1Grids, teamPlayerCount);
170:             PrepareTeamSpawnGrids(ref team2Grids, teamPlayerCount);
171:             PrepareTeamSpawnGrids(ref team3Grids, teamPlayerCount);
172: 
173:             var teamSpawnGrids = new Dictionary<TeamEnum, List<FixVector2>>
174:             {
175:                 [superHeroTeams[0]] = team1Grids,
176:                 [superHeroTeams[1]] = team2Grids,
177:                 [superHeroTeams[2]] = team3Grids,
178:             };
179:             var teamSpawnIndices = new Dictionary<TeamEnum, int>();
180: 
181:             for (int i = 0; i < heroLength; i++)
182:             {
183:                 TeamEnum team = teams[i];
184:                 List<FixVector2> spawnGrids = teamSpawnGrids[team];
185:                 int spawnIndex = teamSpawnIndices.TryGetValue(team, out int index) ? index : 0;
186:                 startGrid = spawnGrids[spawnIndex % spawnGrids.Count];
187:                 teamSpawnIndices[team] = spawnIndex + 1;
