189:                 ++netIndex;
190:             }
191:         }
192:         else if (mapType == MapType.Bun || mapType == MapType.BunPass || mapType == MapType.Hero || mapType == MapType.Fort)
193:         {
194:             //两队 且 双方人数对等
195:             //多人比赛，位置随机
196:             if (heroLength > 2)
197:             {
198:                 int teamCount = heroLength / 2;
199:                 while (team1Grids.Count > teamCount)
200:                 {
201:                     team1Grids.RemoveAt(team1Grids.Count - 1);
202:                 }
203:                 CommonLogic.ShuffleList(_context, ref team1Grids);
204: 
205:                 while (team2Grids.Count > teamCount)
206:                 {
207:                     team2Grids.RemoveAt(team2Grids.Count - 1);
208:                 }
209:                 CommonLogic.ShuffleList(_context, ref team2Grids);
210:             }
211: 
212: 
213:             for (int i = 0; i < heroLength; i++)
214:             {
215:                 TeamEnum team = teams[i];
216:                 if (heroData[i].Team == _context.GetTwoTeamMatch().team1)
217:                 {
218:                     team1_num %= team1Grids.Count;
