547:     private int CreateSpecialItems(List<FixVector2> specialGrids, ItemConfig config, int count, ref HashSet<int> occupied)
548:     {
549:         int availableCount = specialGrids.Count - occupied.Count;
550:         int distributeCount = Math.Min(count, availableCount);
551:         if (distributeCount <= 0)
552:         {
553:             return 0;
554:         }
555: 
556:         List<int> gridPool = DistributeItems(specialGrids.Count, distributeCount, ref occupied);
557:         foreach (int gridIndex in gridPool)
558:         {
559:             CreateAttchItems(specialGrids[gridIndex], config);
560:         }
561: 
562:         return gridPool.Count;
563:     }
