573:     private List<int> DistributeItems(int totalGridCount, int totalItemCount, ref HashSet<int> occupied)
574:     {
575:         List<int> selectedIndices = new List<int>();
576: 
577:         if (totalItemCount > totalGridCount)
578:         {
579:             this.Error("DistributeItems error, totalGridCount:{0}, totalItemCount:{1}", totalGridCount, totalItemCount);
580:             return selectedIndices;
581:         }
582: 
583:         double interval = (double)totalGridCount / totalItemCount;
584: 
585:         for (int i = 0; i < totalItemCount; i++)
586:         {
587:             // 计算当前间隔的起始和结束
588:             double start = i * interval;
589:             double end = (i + 1) * interval;
590: 
591:             // 在[start, end)范围内随机选择一个位置
592:             int position = (int)Math.Floor(start + _context.GetRandom().value.NextDouble() * (end - start));
593: 
594:             // 确保位置在0到n-1之间
595:             position = Math.Max(0, Math.Min(totalGridCount - 1, position));
596: 
597:             // 处理冲突，如果位置已被占用，向前或向后查找最近的未占用的位置
598:             if (occupied.Contains(position))
599:             {
600:                 bool found = false;
601:                 int maxOffset = Math.Max(position, totalGridCount - position - 1);
602:                 // 随机决定先向前还是向后搜索
603:                 bool searchForwardFirst = _context.GetRandom().value.Next(2) == 0;
604: 
605:                 for (int offset = 1; offset <= maxOffset; offset++)
606:                 {
607:                     if (searchForwardFirst)
608:                     {
609:                         // 向后查找
610:                         int newPos = position + offset;
611:                         if (newPos < totalGridCount && !occupied.Contains(newPos))
612:                         {
613:                             position = newPos;
614:                             found = true;
615:                             break;
616:                         }
617: 
618:                         // 向前查找
619:                         newPos = position - offset;
620:                         if (newPos >= 0 && !occupied.Contains(newPos))
621:                         {
622:                             position = newPos;
623:                             found = true;
624:                             break;
625:                         }
626:                     }
627:                     else
628:                     {
629:                         // 向前查找
630:                         int newPos = position - offset;
631:                         if (newPos >= 0 && !occupied.Contains(newPos))
632:                         {
633:                             position = newPos;
634:                             found = true;
635:                             break;
636:                         }
637: 
638:                         // 向后查找
639:                         newPos = position + offset;
640:                         if (newPos < totalGridCount && !occupied.Contains(newPos))
641:                         {
642:                             position = newPos;
643:                             found = true;
644:                             break;
645:                         }
646:                     }
647:                 }
648: 
649:                 // 如果在初始间隔范围内未找到，扩展搜索整个范围
650:                 if (!found)
651:                 {
652:                     for (int newPos = 0; newPos < totalGridCount; newPos++)
653:                     {
654:                         if (!occupied.Contains(newPos))
655:                         {
656:                             position = newPos;
657:                             found = true;
658:                             break;
659:                         }
660:                     }
661:                 }
662:             }
663: 
664:             // 最终选择的位置
665:             selectedIndices.Add(position);
666:             occupied.Add(position);
667:         }
668: 
669:         selectedIndices.Sort();
670:         return selectedIndices;
671:     }
