173:     public void Initialize()
174:     {
175:         HashSet<int> bombIds = new HashSet<int>();
176:         CollectRoleBombIds(bombIds);
177:         CollectAIBombIds(bombIds);
178:         CollectMapRuleBombIds(bombIds);
179:         CollectFixedBattleBombIds(bombIds);
180: 
181:         float startTime = Time.realtimeSinceStartup;
182:         BombPrewarmUtility.PrewarmBombs(bombIds);
183:         float durationMs = (Time.realtimeSinceStartup - startTime) * 1000f;
184:         this.Log("Bomb prewarm init done. count:{0}, cost:{1:F2}ms", bombIds.Count, durationMs);
