187:     private void CollectRoleBombIds(HashSet<int> bombIds)
188:     {
189:         if (_context.GetHeroArr().value == null)
190:         {
191:             return;
192:         }
193: 
194:         foreach (Game.Entity hero in _context.GetHeroArr().value)
195:         {
196:             if (hero == null || !hero.HasBombConfig() || hero.GetBombConfig().value == null)
197:             {
198:                 continue;
199:             }
200: 
201:             bombIds.Add(hero.GetBombConfig().value.Id);
202:         }
203:     }
