205:     private void CollectAIBombIds(HashSet<int> bombIds)
206:     {
207:         if (!_context.HasAIPlayerArr() || _context.GetAIPlayerArr().value == null)
208:         {
209:             return;
210:         }
211: 
212:         foreach (Game.Entity aiPlayer in _context.GetAIPlayerArr().value)
213:         {
214:             if (aiPlayer == null || !aiPlayer.HasBombConfig() || aiPlayer.GetBombConfig().value == null)
215:             {
216:                 continue;
217:             }
218: 
219:             bombIds.Add(aiPlayer.GetBombConfig().value.Id);
220:         }
221:     }
222: 
223:     private void CollectMapRuleBombIds(HashSet<int> bombIds)
224:     {
225:         if (_context.GetMapType().value != MapType.Bomb)
226:         {
227:             return;
228:         }
229: 
230:         List<DropBombConfig> dropBombConfigs = _context.GetConfigService().instance.GetBombMapConfig(PlayerDataManager.Instance.MapConfig.ID);
231:         if (dropBombConfigs == null)
232:         {
233:             return;
234:         }
235: 
236:         foreach (DropBombConfig dropBombConfig in dropBombConfigs)
237:         {
238:             if (dropBombConfig == null)
239:             {
240:                 continue;
241:             }
242: 
243:             bombIds.Add(dropBombConfig.DropBombID);
244:         }
245:     }
