5: /// <summary>
6: /// 探险模式区域遮罩：只对本地主控玩家当前激活区域闪烁。
7: /// </summary>
8: public class RegionMaskView : MonoBehaviour
9: {
10:     private const float FlashDuration = 0.3f;
11:     private const float FlashCooldown = 0.45f;
12:     private const float FlashAlpha = 0.12f;
13:     private const int MaskSortingOrder = 30000;
14: 
15:     private readonly Dictionary<int, SpriteRenderer> masks = new Dictionary<int, SpriteRenderer>();
16:     private int flashingRegionId;
17:     private float flashStartTime;
18:     private float lastFlashTime = -999f;
19: 
20:     private static Sprite whiteSprite;
21: 
22:     public void Init(GameContext context, List<RegionInfo> regions, Transform parent)
23:     {
24:         if (regions == null || regions.Count == 0)
25:             return;
26: 
27:         for (int i = 0; i < regions.Count; i++)
28:         {
29:             RegionInfo region = regions[i];
30:             if (region == null || region.id <= 0)
31:                 continue;
32: 
33:             GameObject go = new GameObject("RegionMask_" + region.id);
34:             go.transform.SetParent(parent, false);
35: 
36:             SpriteRenderer renderer = go.AddComponent<SpriteRenderer>();
37:             renderer.sprite = GetWhiteSprite();
38:             renderer.color = new Color(0f, 0f, 0f, 0f);
39:             renderer.sortingOrder = MaskSortingOrder;
40: 
41:             float centerX = region.x + region.w * 0.5f - 0.5f;
42:             float centerY = region.y + region.h * 0.5f - 0.5f;
43:             FixVector2 center = CommonLogic.GetPositionByGrid(
44:                 new FixVector2((Fix)centerX, (Fix)centerY));
45:             go.transform.localPosition = new Vector3(center.x.RawFloat, center.y.RawFloat, 0f);
46:             go.transform.localScale = new Vector3(
47:                 region.w * GridConstant.GridSize.RawFloat,
48:                 region.h * GridConstant.GridSize.RawFloat,
49:                 1f);
50: 
51:             masks[region.id] = renderer;
52:         }
53: 
54:         EventSvc.Instance.AddEvtListener(EvtID.BATTLE_REGION_LOCKED, OnRegionLocked);
55:     }
56: 
57:     private void OnRegionLocked(object arg1, object arg2)
58:     {
59:         if (!(arg1 is int))
60:             return;
61: 
62:         int regionId = (int)arg1;
63:         if (!masks.ContainsKey(regionId))
64:             return;
65: 
66:         float now = Time.unscaledTime;
67:         if (now - lastFlashTime < FlashCooldown)
68:             return;
69: 
70:         lastFlashTime = now;
71:         flashingRegionId = regionId;
72:         flashStartTime = now;
73:     }
74: 
75:     private void Update()
76:     {
77:         if (flashingRegionId == 0 || !masks.TryGetValue(flashingRegionId, out SpriteRenderer renderer))
78:             return;
79: 
80:         float t = (Time.unscaledTime - flashStartTime) / FlashDuration;
81:         if (t >= 1f)
82:         {
83:             renderer.color = new Color(0f, 0f, 0f, 0f);
84:             flashingRegionId = 0;
85:             return;
86:         }
87: 
88:         float alpha = Mathf.Sin(t * Mathf.PI) * FlashAlpha;
89:         renderer.color = new Color(0f, 0f, 0f, alpha);
90:     }
91: 
92:     private void OnDestroy()
93:     {
94:         if (EventSvc.Instance != null)
95:             EventSvc.Instance.RmvEvtListener(EvtID.BATTLE_REGION_LOCKED);
96:     }
97: 
98:     private static Sprite GetWhiteSprite()
99:     {
100:         if (whiteSprite == null)
101:         {
102:             Texture2D texture = new Texture2D(1, 1, TextureFormat.RGBA32, false);
103:             texture.SetPixel(0, 0, Color.white);
104:             texture.Apply();
105:             texture.filterMode = FilterMode.Point;
106: 
107:             whiteSprite = Sprite.Create(
108:                 texture,
109:                 new Rect(0f, 0f, 1f, 1f),
110:                 new Vector2(0.5f, 0.5f),
111:                 1f);
112:         }
113: 
114:         return whiteSprite;
