93:     private static bool GetPassableReason(GameContext context, Game.Entity entity, FixVector2 gridID, MoveDirectionType directionType,
94:         bool includeLocalBomb, out StopReason reason)
95:     {
96:         if (RegionLogic.IsBlockedByRegion(context, entity, gridID))
97:         {
98:             reason = StopReason.RegionLocked;
99:             return false;
100:         }
101: 
102:         if (CommonLogic.HasBomb(context, gridID) || (includeLocalBomb && CommonLogic.HasBombLocal(context, gridID)))
103:         {
104:             reason = StopReason.Bomb;
105:             return false;
106:         }
107: 
108:         if (CommonLogic.HasObs(context, gridID))
109:         {
110:             reason = StopReason.Box;
111:             return false;
112:         }
113: 
114:         Game.Entity door = CommonLogic.GetDoor(context, gridID);
115:         if (door != null)
116:         {
117:             DoorDirType doorDir = door.GetDoorDirType().value;
118:             if (doorDir == DoorDirType.Verticle)
119:             {
120:                 if (directionType == MoveDirectionType.Left || directionType == MoveDirectionType.Right)
121:                 {
122:                     reason = StopReason.Box;
123:                     return false;
124:                 }
125:             }
126:             else if (doorDir == DoorDirType.Horizontal)
127:             {
128:                 if (directionType == MoveDirectionType.Up || directionType == MoveDirectionType.Down)
129:                 {
130:                     reason = StopReason.Box;
131:                     return false;
132:                 }
133:             }
134:         }
135: 
136:         reason = StopReason.None;
137:         return true;
