private void CreateMapItems(MapConfig mapConfig)
{
    int heroCount = _context.GetHeroArr().value.Length;
    if (heroCount <= 0) heroCount = 1;
    List<MapBrickItemConfig> itemConfigs = mapConfig.GetBrickItemsByPlayerNum(heroCount);
    if (itemConfigs == null || itemConfigs.Count == 0) return;

    List<FixVector2> grids = new List<FixVector2>();
    foreach (Game.Entity brick in _context.GetMapElems().brickList)
        grids.Add(brick.GetGridID().value);
    foreach (Game.Entity brick in _context.GetMapElems().moveBrickList)
        grids.Add(brick.GetGridID().value);
    if (grids.Count == 0) return;

    HashSet<int> occupied = new HashSet<int>();
    for (int i = 0; i < itemConfigs.Count; i++)
    {
        MapBrickItemConfig itemConfig = itemConfigs[i];
        ItemConfig config = _context.GetConfigService().instance.GetItemConfig(itemConfig.itemID);
        if (config == null) continue;

        int count = _context.GetRandom().value.Next(itemConfig.minCount, itemConfig.maxCount + 1);
        for (int j = 0; j < count; j++)
        {
            if (occupied.Count >= grids.Count) return;
            int index = _context.GetRandom().value.Next(0, grids.Count);
            int guard = 0;
            while (occupied.Contains(index) && guard < grids.Count)
            {
                index = (index + 1) % grids.Count;
                guard++;
            }
            if (occupied.Contains(index)) continue;
            occupied.Add(index);

            Game.Entity item = _context.GetEntityFactoryService().instance.CreateItemEntity(
                UidUtils.Uid, grids[index], config);
            item.ReplaceItemState(ItemState.AttachBelow);
        }
    }
}
