using Entitas;
using Entitas.Generators.Attributes;

/// <summary>
/// 局内换图状态。状态变化时，各系统自行重置数据。
/// </summary>
public enum ChangeMapState
{
    None,
    Clear,
    WaitDestroy,
    Build,
    ResetSpawner,
    Place,
    Prepare,
    WaitInGame,
}

[Context(typeof(GameContext)), Unique]
public sealed class ChangeMapComponent : IComponent
{
    public ChangeMapState state;
    public int mapID;
}

using Entitas;
using PBProto;
using SimpleFixMath;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 局内换图。当前为测试逻辑：2002 通关后重新进入 2002。
/// 仅支持行列数一致的地图，因此保留 MapGrids / MapBounds，只重建地图元素和刷怪。
/// </summary>
public class ChangeMapSystem : IInitializeSystem, IExecuteSystem, ITearDownSystem
{
    public const int TestNextMapID = 2002; // TODO: 后续从配置表读取

    private readonly GameContext _context;

    public ChangeMapSystem(GameContext context)
    {
        _context = context;
    }

    public void Initialize()
    {
        if (!_context.HasChangeMap())
            _context.ReplaceChangeMap(ChangeMapState.None, 0);
    }

    public void TearDown()
    {
        ResetData();
    }

    public void ResetData()
    {
        _context.ReplaceChangeMap(ChangeMapState.None, 0);
    }

    public void Execute()
    {
        if (!_context.HasChangeMap())
            return;

        ChangeMapComponent changeMap = _context.GetChangeMap();
        switch (changeMap.state)
        {
            case ChangeMapState.None:
                return;
            case ChangeMapState.Clear:
                ClearScene();
                _context.ReplaceChangeMap(ChangeMapState.WaitDestroy, changeMap.mapID);
                break;
            case ChangeMapState.WaitDestroy:
                _context.ReplaceChangeMap(ChangeMapState.Build, changeMap.mapID);
                break;
            case ChangeMapState.Build:
                BuildMap(changeMap.mapID);
                _context.ReplaceChangeMap(ChangeMapState.ResetSpawner, changeMap.mapID);
                break;
            case ChangeMapState.ResetSpawner:
                PlaceHeroes();
                _context.ReplaceChangeMap(ChangeMapState.Place, changeMap.mapID);
                break;
            case ChangeMapState.Place:
                _context.ReplaceChangeMap(ChangeMapState.Prepare, changeMap.mapID);
                break;
            case ChangeMapState.Prepare:
                PrepareNextMap();
                _context.ReplaceChangeMap(ChangeMapState.WaitInGame, changeMap.mapID);
                break;
            case ChangeMapState.WaitInGame:
                if (_context.GetGameProgress().value == GameProgressState.InGame)
                    ResetData();
                break;
        }
    }

    private void ClearScene()
    {
        Game.Entity[] entities = _context.GetEntities();
        for (int i = 0; i < entities.Length; i++)
        {
            Game.Entity entity = entities[i];
            if (!entity.HasUnitType())
                continue;

            switch (entity.GetUnitType().value)
            {
                case UnitType.Hero:
                case UnitType.BagItem:
                case UnitType.MapGrid:
                    continue;
                default:
                    entity.AddDestroyed();
                    break;
            }
        }

        if (_context.HasBombShape())
            _context.GetBombShape().shapes.Clear();

        if (_context.HasAIPlayerArr() && _context.GetAIPlayerArr().value != null)
        {
            for (int i = 0; i < _context.GetAIPlayerArr().value.Length; i++)
                _context.GetAIPlayerArr().value[i] = null;
        }

        ItemBirdComponent itemBird = _context.GetItemBird();
        itemBird.queue.Clear();
        itemBird.timer = Fix.zero;
        itemBird.state = ItemBirdState.None;
    }

    private void BuildMap(int mapID)
    {
        MapConfig mapConfig = _context.GetConfigService().instance.GetMapConfig(mapID);
        if (mapConfig == null)
        {
            _context.Error("ChangeMapSystem: can't find map config {0}", mapID);
            _context.ReplaceGameProgress(GameProgressState.InGame);
            ResetData();
            return;
        }

        PlayerDataManager.Instance.MapConfig = mapConfig;
        _context.ReplaceMapConfig(mapConfig);

        int col = mapConfig.col;
        int row = mapConfig.row;

        _context.ReplaceMapElems(
            new Game.Entity[col, row],
            new Game.Entity[col, row],
            new Game.Entity[col, row],
            new List<Game.Entity>(),
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row],
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row],
            new Game.Entity[col, row], new List<Game.Entity>(),
            new int[col, row]);

        _context.ReplaceBuildings(
            new Game.Entity[col, row], new List<Game.Entity>(),
            new Game.Entity[col, row], new List<Game.Entity>());

        _context.ReplaceMapFloor(new Game.Entity[col, row]);

        List<Game.Entity>[,] bombsArr = new List<Game.Entity>[col, row];
        for (int i = 0; i < col; i++)
        {
            for (int j = 0; j < row; j++)
                bombsArr[i, j] = new List<Game.Entity>();
        }
        _context.ReplaceBombs(bombsArr, new List<Game.Entity>());

        Queue<Game.Entity>[,] itemQueues = new Queue<Game.Entity>[col, row];
        for (int i = 0; i < col; i++)
        {
            for (int j = 0; j < row; j++)
                itemQueues[i, j] = new Queue<Game.Entity>();
        }
        _context.ReplaceItems(itemQueues, new List<Game.Entity>());

        _context.ReplaceViewField(new int[col, row]);
        _context.ReplaceFlames(new Game.Entity[col, row], new List<Game.Entity>(), new List<Game.Entity>());
        _context.ReplaceBlowUpFlames(new Game.Entity[col, row], new List<Game.Entity>());

        if (PlayerDataManager.Instance.IsBossMode || PlayerDataManager.Instance.IsAIPlayerMode)
        {
            _context.ReplaceAtkPlayerGrid(new int[col, row], new int[8]);
            _context.ReplacePathScoreGlobal(new int[col, row]);
        }

        CreateBuildings(mapConfig);
        CreateMapElems(mapConfig.floorArr, col, row);
        CreateMapElems(mapConfig.wallArr, col, row);
        CreateMapElems(mapConfig.brickArr, col, row);
        CreateMapElems(mapConfig.moveBrickArr, col, row);
        CreateMapElems(mapConfig.composeWallArr, col, row);
        CreateMapElems(mapConfig.doorArr, col, row);
        CreateMapElems(mapConfig.grassArr, col, row);
        CreateMapElems(mapConfig.riverArr, col, row);
        CreateMapElems(mapConfig.pinFloorArr, col, row);
        CreateMapElems(mapConfig.spikeWallArr, col, row);
        CreateMapElems(mapConfig.totemArr, col, row);

        CreateMapItems(mapConfig);

        List<BattleDropData> drops = mapConfig.bossdrops;
        if (drops == null)
            drops = new List<BattleDropData>();
        _context.ReplaceMapAIDrop(drops);

        CheckMapOverride(mapConfig);

        if (_context.HasBossModeState())
            _context.ReplaceBossModeState(BossModeState.None);

        if (ViewManager.Instance != null)
            ViewManager.Instance.SetMapConfig(mapConfig);
    }

    private void PlaceHeroes()
    {
        MapConfig mapConfig = PlayerDataManager.Instance.MapConfig;
        List<FixVector2> spawns = mapConfig.team1StartGrid;
        if (spawns == null || spawns.Count == 0)
            spawns = mapConfig.AllStartGrids;

        if (spawns == null || spawns.Count == 0)
        {
            _context.Error("ChangeMapSystem: map {0} has no start grid", mapConfig.ID);
            return;
        }

        Game.Entity[] heroes = _context.GetHeroArr().value;
        for (int i = 0; i < heroes.Length; i++)
        {
            Game.Entity hero = heroes[i];
            if (hero == null || hero.HasDestroyed())
                continue;

            FixVector2 grid = spawns[i % spawns.Count];
            FixVector2 position = CommonLogic.GetPositionByGrid(grid);

            hero.ReplaceGridID(grid);
            hero.ReplaceLastGridID(grid);
            hero.ReplacePosition(position);
            hero.ReplaceInputDirection(MoveDirectionType.Stop, MoveDirectionType.Down);
            hero.ReplaceMoveDirection(MoveDirectionType.Stop);
            hero.ReplaceRoleState(RoleState.Alive);
            hero.ReplaceTrappedEndTime(Fix.zero);
            hero.ReplaceRelifeInfo(Fix.zero, grid);
            hero.ReplaceCanBomb(true);
            hero.ReplaceUnexplodeBomb(0);
            hero.ReplaceTransparentBombEndTime(Fix.zero);
            hero.ReplaceKillerUid(0);
            hero.ReplacePickType(TeamEnum.None);
            hero.ReplaceFirstEnterGrid(false);
            hero.ReplaceMovable(true);

            if (hero.HasSpringJump())
                hero.RemoveSpringJump();
        }

        if (_context.HasMainPlayerInfos())
        {
            MainPlayerInfosComponent infos = _context.GetMainPlayerInfos();
            Game.Entity mainPlayer = infos.logicEntity;
            if (mainPlayer != null && !mainPlayer.HasDestroyed())
            {
                Vector2 pos = mainPlayer.GetPosition().value.ToView();
                infos.moveDir = MoveDirectionType.Stop;
                infos.faceDir = MoveDirectionType.Down;
                infos.pos.SetValue(pos);
                infos.lastPos = pos;
            }
        }

        BattleSystem.Instance?.ResetLocalLogicData();
    }

    private void PrepareNextMap()
    {
        int mapTime = (int)PlayerDataManager.Instance.GameTotalTime;
        if (mapTime <= 0)
            mapTime = 240;

        _context.ReplaceGameTotalSec(_context.GetGameTime().value.RawInt + mapTime);
        EventSvc.Instance.SendEvt(EvtID.BATTLE_UPDATE_LEFT_TIME, mapTime);
        _context.ReplaceGameProgress(GameProgressState.StartGame);
    }

    private void CreateMapElems(int[] arr, int col, int row)
    {
        if (arr == null || arr.Length == 0)
            return;

        for (int i = 0; i < col; i++)
        {
            for (int j = 0; j < row; j++)
            {
                int index = j * col + i;
                if (index >= arr.Length)
                    continue;

                int assetID = arr[index];
                if (assetID <= 0)
                    continue;

                MapElemType realElemType = MapElemConfigs.GetMapElemType(assetID);
                DoorDirType doorDirType = realElemType == MapElemType.Door
                    ? _context.GetConfigService().instance.GetDoorConfig(assetID).dir
                    : DoorDirType.None;

                _context.GetEntityFactoryService().instance.CreateMapElemEntiy(
                    UidUtils.Uid, assetID, new FixVector2(i, j), realElemType, doorDirType);
            }
        }
    }

    private void CreateBuildings(MapConfig mapConfig)
    {
        if (mapConfig.buildingInfoArr == null || mapConfig.buildingInfoArr.Length == 0)
            return;

        MapElemType elemType;
        switch (_context.GetMapType().value)
        {
            case MapType.Bun:
                elemType = MapElemType.Bun;
                break;
            case MapType.Hero:
            case MapType.BunPass:
            case MapType.SuperHero:
                elemType = MapElemType.Sculpture;
                break;
            default:
                return;
        }

        for (int i = 0; i < mapConfig.buildingInfoArr.Length; i++)
        {
            BuildingInfo info = mapConfig.buildingInfoArr[i];
            if (info == null || info.assetID <= 0)
                continue;

            int x = info.posIndex % mapConfig.col;
            int y = info.posIndex / mapConfig.col;

            TeamEnum team = TeamEnum.Team1;
            if (elemType == MapElemType.Bun && _context.HasTwoTeamMatch())
            {
                team = info.team == 0
                    ? _context.GetTwoTeamMatch().team1
                    : _context.GetTwoTeamMatch().team2;
            }

            _context.GetEntityFactoryService().instance.CreateBuildingEntiy(
                UidUtils.Uid, info.assetID, new FixVector2(x, y), elemType, team);
        }
    }

    private void CreateMapItems(MapConfig mapConfig)
    {
        int heroCount = _context.GetHeroArr().value.Length;
        if (heroCount <= 0)
            heroCount = 1;

        List<MapBrickItemConfig> itemConfigs = mapConfig.GetBrickItemsByPlayerNum(heroCount);
        if (itemConfigs == null || itemConfigs.Count == 0)
            return;

        List<FixVector2> grids = new List<FixVector2>();
        foreach (Game.Entity brick in _context.GetMapElems().brickList)
            grids.Add(brick.GetGridID().value);
        foreach (Game.Entity brick in _context.GetMapElems().moveBrickList)
            grids.Add(brick.GetGridID().value);

        if (grids.Count == 0)
            return;

        HashSet<int> occupied = new HashSet<int>();
        for (int i = 0; i < itemConfigs.Count; i++)
        {
            MapBrickItemConfig itemConfig = itemConfigs[i];
            if (itemConfig == null)
                continue;

            ItemConfig config = _context.GetConfigService().instance.GetItemConfig(itemConfig.itemID);
            if (config == null)
                continue;

            int count = _context.GetRandom().value.Next(itemConfig.minCount, itemConfig.maxCount + 1);
            for (int j = 0; j < count; j++)
            {
                if (occupied.Count >= grids.Count)
                    return;

                int index = _context.GetRandom().value.Next(0, grids.Count);
                int guard = 0;
                while (occupied.Contains(index) && guard < grids.Count)
                {
                    index = (index + 1) % grids.Count;
                    guard++;
                }

                if (occupied.Contains(index))
                    continue;

                occupied.Add(index);
                Game.Entity item = _context.GetEntityFactoryService().instance.CreateItemEntity(
                    UidUtils.Uid, grids[index], config);
                item.ReplaceItemState(ItemState.AttachBelow);
            }
        }
    }

    private void CheckMapOverride(MapConfig mapConfig)
    {
        var battleMapConfig = _context.GetConfigService().instance.GetBattleMapConfig(mapConfig.ID);
        if (battleMapConfig == null)
            return;

        _context.ReplaceRoleAttributeOverride(
            battleMapConfig.bombPowerMin,
            battleMapConfig.bombPowerMax,
            battleMapConfig.moveSpeedIndexMin,
            battleMapConfig.moveSpeedIndexMax,
            battleMapConfig.bombCountMin,
            battleMapConfig.bombCountMax);
    }
}

