public class FixTimerSystem : IInitializeSystem, IExecuteSystem, ITearDownSystem
{
    private readonly GameContext _context;
    private ITimer mgr;

    public FixTimerSystem(GameContext contexts)
    {
        _context = contexts;
        mgr = _context.GetTimerService().instance;
    }

    public void Initialize()
    {
        _context.GetGroup(GameChangeMapMatcher.ChangeMap).OnEntityUpdated += OnChangeMapUpdated;
    }

    public void Execute()
    {
        mgr.Tick(_context.GetLogicDT().value);
    }

    public void TearDown()
    {
        _context.GetGroup(GameChangeMapMatcher.ChangeMap).OnEntityUpdated -= OnChangeMapUpdated;
    }

    private void OnChangeMapUpdated(IGroup<Game.Entity> group, Game.Entity entity, int index, IComponent previousComponent, IComponent newComponent)
    {
        ChangeMapComponent changeMap = newComponent as ChangeMapComponent;
        if (changeMap != null && changeMap.state == ChangeMapState.Clear)
            ResetData();
    }

    public void ResetData()
    {
        mgr.Reset();
    }

}

